def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))
            ob = opp.get('budget', 0)
            if ob >= 140:
                rich_aggressive += 1

    if not alive_opponents:
        return min(budget, 21.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 16.0
    ample_supply = supply >= 22.0
    danger = (hp <= 3) or (no_water >= 2)
    caution = (hp <= 5) or (no_water >= 1)

    if danger:
        bid = max(63.0, highest_prev + 2.0)
        if tight_supply:
            bid = max(bid, 72.0)
        return min(budget, bid)

    if caution:
        if highest_prev >= 95.0:
            bid = 66.0 if tight_supply else 54.0
        else:
            bid = max(50.0, min(74.0, highest_prev + 1.5))
            if ample_supply:
                bid -= 6.0
        return min(budget, max(0.0, bid))

    if highest_prev >= 100.0:
        bid = 12.0 if ample_supply else 18.0
    elif highest_prev >= 90.0:
        bid = 16.0 if ample_supply else 24.0
    elif highest_prev >= 75.0:
        bid = 24.0 if ample_supply else 32.0
    else:
        bid = max(22.0, avg_prev * 0.55)

    if tight_supply:
        bid += 8.0
    if rich_aggressive >= 2:
        bid -= 4.0
    if budget < 80:
        bid = min(bid, 38.0)

    return min(budget, max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and their yesterday bids
    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # If others bid aggressively yesterday, match slightly below the pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Supply pressure: fewer units imply higher competition
    # Expected number of water quanta available (approx, since reward mechanism unknown)
    supply_quanta = supply / float(WATER_REQ)
    # Normalize to [0,1] where 1 means tight supply
    if MAX_SUPPLY == MIN_SUPPLY:
        tightness = 0.5
    else:
        tightness = 1.0 - ((supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY))
        tightness = max(0.0, min(1.0, tightness))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Base bid aggressiveness
    # When tight and HP is not critical, bid near 0.95*DAILY_SALARY.
    # If HP is low, bid more to avoid death.
    if hp <= 2:
        base = DAILY_SALARY * (0.9 + 0.1 * tightness)
    elif hp <= 4:
        base = DAILY_SALARY * (0.75 + 0.2 * tightness)
    else:
        base = DAILY_SALARY * (0.55 + 0.4 * tightness)

    # Reaction to yesterday's max bid: undercut slightly to win if possible
    # Keep within a safe range relative to highest_prev_bid.
    if highest_prev_bid > 0:
        # Target just below the observed ceiling, but not too low.
        target = min(base, highest_prev_bid * 0.97)
        # Also ensure we don't underbid dramatically when others were very high.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, DAILY_SALARY * (0.65 + 0.25 * tightness))
    else:
        target = base

    # Final cap: cannot exceed budget; also avoid extreme overbids
    # Empirically from trace, others maxed around ~104.5-106; cap around 1.2*DAILY_SALARY.
    cap = DAILY_SALARY * 1.2
    bid = min(budget, cap, target)

    # If we are out of budget, bid 0
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if my_status['no_water_days'] >= 1 or my_status['hp'] <= 3:
        # urgent: bid high to secure water
        target = max(DAILY_SALARY * 0.9, DAILY_SALARY * 0.75)
        if yesterday_bids:
            target = max(target, max(yesterday_bids) + 1.5)
    else:
        # can be conservative
        if yesterday_bids:
            max_prev = max(yesterday_bids)
            if max_prev >= DAILY_SALARY * 0.85:
                target = DAILY_SALARY * 0.4
            else:
                target = max(DAILY_SALARY * 0.5, max_prev + 1.5)
        else:
            target = DAILY_SALARY * 0.55
    bid = min(my_status['budget'], target)
    return int(max(0, bid))
